    function invoiceModal(){
    const root=$('#modal-root');
    const html=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>Nova cobrança</h3><button type="button" class="close" data-close aria-label="Fechar"><span class="icon-slot"><i data-lucide="x" class="ui-icon" aria-hidden="true"></i><span class="icon-fallback" aria-hidden="true">×</span></span></button></div><form id="invoice-form" method="post"><div class="form-grid"><div class="field"><label>Cliente<select class="select" name="client_id" required>${S.meta.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label></div><div class="field"><label>Valor<input class="input" id="invoice-amount" name="amount_display" type="text" inputmode="numeric" autocomplete="off" placeholder="R$ 0,00" required></label></div><div class="field span2"><label>Descrição<input class="input" name="description" required></label></div><div class="field"><label>Vencimento<input class="input" name="due_on" type="date" required></label></div></div><div class="form-actions"><button type="button" class="ghost" data-close>Cancelar</button><button type="submit" class="primary">Criar cobrança</button></div></form></div></div>`;
    root.innerHTML=html;
    const form=root.querySelector('#invoice-form'),amount=root.querySelector('#invoice-amount');
    moneyInput(amount,0);
    root.querySelectorAll('[data-close]').forEach(btn=>btn.addEventListener('click',closeModal));
    form.addEventListener('submit',async e=>{
      e.preventDefault();
      e.stopPropagation();
      const btn=e.submitter,old=btn?.textContent;
      if(btn){btn.disabled=true;btn.textContent='Criando…'}
      try{
        const p=Object.fromEntries(new FormData(form));
        p.amount_cents=currencyCents(amount);
        delete p.amount_display;
        if(p.amount_cents<1)throw new Error('Informe um valor maior que R$ 0,00.');
        await api('invoices.create',p,'POST');
        toast('Cobrança criada');
        closeModal();
        await stableRender(renderFinance);
      }catch(x){
        toast(x.message||'Não foi possível criar a cobrança.',true);
        if(btn){btn.disabled=false;btn.textContent=old}
      }
    });
    setTimeout(()=>amount?.focus(),0);
  }
